def page(title,desc,body,active='',home=False):
 path='index.html' if home else f'html/{active}.html'
 return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#153d36"><title>{title} · Ersan’s Kebap</title><meta name="description" content="{e(desc)}"><meta property="og:title" content="{e(title)} · Ersan’s Kebap"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="https://www.ersans-kebap.de/img/optimized/hero-kebap.webp"><meta name="color-scheme" content="light"><link rel="icon" href="@/img/favicon.svg" type="image/svg+xml"><link rel="preload" href="@/fonts/instrument-serif-normal.woff" as="font" type="font/woff" crossorigin><link rel="stylesheet" href="@/css/styles.css?v=20261015-readable"><script src="@/js/app.js" defer></script></head><body id="top" class="{active} {'is-home' if home else ''}">{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
def write(file,text):
 p=ROOT/file;p.parent.mkdir(parents=True,exist_ok=True);prefix='../'*(len(Path(file).parts)-1) or './';text=text.replace('@/',prefix)
 text=re.sub(r'(?=</?(?:section|header|footer|main|nav|article|aside|div|form|ul|li|dl|dt|dd|label|h1|h2|h3|p|script|meta|link|body|head|html|input|textarea|details|summary)\b)', '\n', text)
 text='\n'.join(line.rstrip() for line in text.splitlines())
 text=re.sub(r'\n{3,}', '\n\n', text)
 p.write_text(text.strip()+'\n')
