story=f'''<section class="story-hero shell"><div><p class="eyebrow">DAS SIND WIR.</p><h1>Unser Laden.<br>Unsere Geschichte.<br><em>Dein Ersan’s.</em></h1><p>Ein familiärer Imbiss in Dinkelsbühl.<br>Mit viel Arbeit aufgebaut. Mit Herz weitergemacht.</p><a class="under-link" href="#geschichte">Unsere Geschichte entdecken ↓</a></div><div class="story-hero-photo">{image('neuer-laden2','Ersan bei der Zubereitung in seinem Laden','',False)}<span class="image-caption">ECHTE MENSCHEN. ECHTES HANDWERK.</span></div></section><section class="story-statement shell section" data-reveal><span class="eyebrow">WARUM WIR DAS MACHEN.</span><p>Weil gutes Essen Menschen zusammenbringt.<br>Und weil ein kleiner Laden <em>viel Herz haben kann.</em></p></section><section class="journey shell" id="geschichte"><article class="journey-chapter" data-reveal><div class="chapter-photos"><button type="button" data-gallery="renovierung" data-gallery-index="0" aria-label="Renovierung vergrößert ansehen">{image('laden-vorher1','Der neue Standort während der Renovierung')}</button><button type="button" data-gallery="renovierung" data-gallery-index="1" aria-label="Zweites Renovierungsfoto vergrößern">{image('laden-vorher2','Der renovierte Gastraum')}</button></div><div class="chapter-copy"><span class="chapter-number">01 / DER ANFANG</span><h2>Eine Idee.<br><em>Ein neuer Ort.</em></h2><p>Ein neuer Standort und jede Menge Arbeit: Wir haben renoviert und eingerichtet, um einen Ort zu schaffen, an dem frisches Essen und eine familiäre Atmosphäre zusammenkommen.</p></div></article><article class="journey-chapter reversed" data-reveal><div class="chapter-photos"><button type="button" data-gallery="wasserschaden" data-gallery-index="0" aria-label="Foto vom Wasserschaden ansehen">{image('wasserschaden1','Der Wasserschaden im frisch renovierten Laden')}</button><button type="button" data-gallery="wasserschaden" data-gallery-index="1" aria-label="Weiteres Foto vom Wasserschaden ansehen">{image('wasserschaden2','Die Folgen des Wasserschadens')}</button></div><div class="chapter-copy"><span class="chapter-number">02 / DER RÜCKSCHLAG</span><h2>Kurz zurück.<br><em>Dann weiter.</em></h2><p>Gerade war alles fertig, da kam ein Wasserschaden. Nach der vielen Arbeit war das ein harter Rückschlag. Trotzdem stand für uns fest: Wir machen weiter.</p></div></article><article class="journey-chapter" data-reveal><div class="chapter-photos"><button type="button" data-gallery="neustart" data-gallery-index="0" aria-label="Ersan am Ofen vergrößert ansehen">{image('neuer-laden1','Ersan am Ofen nach dem Neustart')}</button><button type="button" data-gallery="neustart" data-gallery-index="1" aria-label="Ersan im Laden vergrößert ansehen">{image('neuer-laden2','Ersan bereitet ein Gericht zu')}</button></div><div class="chapter-copy"><span class="chapter-number">03 / DER NEUSTART</span><h2>Wieder da.<br><em>Für dich.</em></h2><p>Heute stehen wir wieder für euch im Laden, bereiten zu und freuen uns über bekannte und neue Gesichter. Danke an alle, die uns auf diesem Weg unterstützt haben.</p>{button('Die Speisekarte entdecken','@/html/menu.html','outline')}</div></article></section>{visit()}'''
